window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-97281b8bf6fa8057"]={"versions": [{"id": "FIG-97281b8bf6fa8057", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Dateistruktur-Diagramm zur Darstellung der statischen Inklusionsbeziehungen (Header- und Source-Abhängigkeiten) des AUTOSAR Classic Platform BSW-Moduls EthTSyn (Time Synchronization over Ethernet). Die Schichtenarchitektur verortet das Modul innerhalb der Kommunikations- und Systemdienste mit Querverbindungen zu Ethernet-Treiberschichten, Fehlermanagement und Zustandsverwaltung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm modelliert Quell- und Header-Dateien als Entitäten mit den Stereotypen «source» und «header»:</p>\n<ul class=\"fig-list\">\n<li><code>EthTSyn.c</code> («source»): Zentrale Implementierungsdatei des Moduls.</li>\n<li><code>EthTSyn.h</code> («header»): Modul-Hauptheader.</li>\n<li><code>EthTSyn_Types.h</code> («header»): Modulspezifische Typdefinitionen.</li>\n<li><code>ComStack_Types.h</code> («header»): Standardisierte Kommunikationsstapel-Basistypen.</li>\n<li><code>FrTSyn_Cfg.h</code> («header»): Konfigurationsheader (offensichtlicher Tippfehler/Copy-Paste-Fehler im Standard-Modell anstelle von <code>EthTSyn_Cfg.h</code>).</li>\n<li><code>EthTSyn_MemMap.h</code> («header»): Memory-Mapping-Definitionen des Moduls.</li>\n<li><code>EthIf.h</code> («header»): Schnittstelle zur Ethernet-Schnittstellenschicht (Ethernet Interface).</li>\n<li><code>Det.h</code> («header»): Schnittstelle zum Default Error Tracer.</li>\n<li><code>BswM.h</code> («header»): Schnittstelle zum BSW Mode Manager.</li>\n<li><code>StbM.h</code> («header»): Schnittstelle zum Synchronized Time-Base Manager.</li>\n</ul>\n<p class=\"fig-p\">Beziehungen (gerichtete gestrichelte Abhängigkeitspfeile mit Stereotypen):</p>\n<ul class=\"fig-list\">\n<li><code>EthTSyn.c</code> inkludiert via «includes»: <code>EthTSyn.h</code>, <code>EthTSyn_MemMap.h</code>, <code>EthIf.h</code>, <code>BswM.h</code>, <code>StbM.h</code>.</li>\n<li><code>EthTSyn.c</code> inkludiert via «includes, optional»: <code>Det.h</code>.</li>\n<li><code>EthTSyn.h</code> inkludiert via «includes»: <code>EthTSyn_Types.h</code> und <code>FrTSyn_Cfg.h</code>.</li>\n<li><code>EthTSyn_Types.h</code> inkludiert via «includes»: <code>ComStack_Types.h</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Include-Strukturdiagramm stellt die Abbildung keine dynamischen Aufruffolgen oder zeitlichen Sequenzen dar. Die gerichteten Abhängigkeiten determinieren jedoch die Reihenfolge der Präprozessor-Inklusionen bei der Kompilierung: <code>ComStack_Types.h</code> bildet die Basis für <code>EthTSyn_Types.h</code>, welche wiederum vor <code>EthTSyn.h</code> aufgelöst wird. <code>EthTSyn.c</code> aggregiert die Modul-Header sowie die externen BSW-Schnittstellen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für die Dateiorganisation und Inklusionshierarchie bei der BSW-Modulentwicklung von <code>EthTSyn</code>. Der optionale Einschluss von <code>Det.h</code> spiegelt den üblichen Präprozessorschalter für Entwicklungs-Fehlererkennung (<code>ETHTSYN_DEV_ERROR_DETECT</code>) wider. Auffällig ist die Benennung von <code>FrTSyn_Cfg.h</code>, die bei der Implementierung von <code>EthTSyn</code> redaktionell als <code>EthTSyn_Cfg.h</code> zu interpretieren bzw. abzugleichen ist. <code>EthTSyn_MemMap.h</code> ist für Speicherkonfiguration und Compilerabstraktion strikt einzubinden.</p>"}, {"id": "FIG-f5c2fc5c1356e87a", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Dateistruktur-Diagramm zur Darstellung der statischen Inklusionsbeziehungen (Header- und Source-Abhängigkeiten) des AUTOSAR Classic Platform BSW-Moduls EthTSyn (Time Synchronization over Ethernet). Die Schichtenarchitektur verortet das Modul innerhalb der Kommunikations- und Systemdienste mit Querverbindungen zu Ethernet-Treiberschichten, Fehlermanagement und Zustandsverwaltung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm modelliert Quell- und Header-Dateien als Entitäten mit den Stereotypen «source» und «header»:</p>\n<ul class=\"fig-list\">\n<li><code>EthTSyn.c</code> («source»): Zentrale Implementierungsdatei des Moduls.</li>\n<li><code>EthTSyn.h</code> («header»): Modul-Hauptheader.</li>\n<li><code>EthTSyn_Types.h</code> («header»): Modulspezifische Typdefinitionen.</li>\n<li><code>ComStack_Types.h</code> («header»): Standardisierte Kommunikationsstapel-Basistypen.</li>\n<li><code>FrTSyn_Cfg.h</code> («header»): Konfigurationsheader (offensichtlicher Tippfehler/Copy-Paste-Fehler im Standard-Modell anstelle von <code>EthTSyn_Cfg.h</code>).</li>\n<li><code>EthTSyn_MemMap.h</code> («header»): Memory-Mapping-Definitionen des Moduls.</li>\n<li><code>EthIf.h</code> («header»): Schnittstelle zur Ethernet-Schnittstellenschicht (Ethernet Interface).</li>\n<li><code>Det.h</code> («header»): Schnittstelle zum Default Error Tracer.</li>\n<li><code>BswM.h</code> («header»): Schnittstelle zum BSW Mode Manager.</li>\n<li><code>StbM.h</code> («header»): Schnittstelle zum Synchronized Time-Base Manager.</li>\n</ul>\n<p class=\"fig-p\">Beziehungen (gerichtete gestrichelte Abhängigkeitspfeile mit Stereotypen):</p>\n<ul class=\"fig-list\">\n<li><code>EthTSyn.c</code> inkludiert via «includes»: <code>EthTSyn.h</code>, <code>EthTSyn_MemMap.h</code>, <code>EthIf.h</code>, <code>BswM.h</code>, <code>StbM.h</code>.</li>\n<li><code>EthTSyn.c</code> inkludiert via «includes, optional»: <code>Det.h</code>.</li>\n<li><code>EthTSyn.h</code> inkludiert via «includes»: <code>EthTSyn_Types.h</code> und <code>FrTSyn_Cfg.h</code>.</li>\n<li><code>EthTSyn_Types.h</code> inkludiert via «includes»: <code>ComStack_Types.h</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Include-Strukturdiagramm stellt die Abbildung keine dynamischen Aufruffolgen oder zeitlichen Sequenzen dar. Die gerichteten Abhängigkeiten determinieren jedoch die Reihenfolge der Präprozessor-Inklusionen bei der Kompilierung: <code>ComStack_Types.h</code> bildet die Basis für <code>EthTSyn_Types.h</code>, welche wiederum vor <code>EthTSyn.h</code> aufgelöst wird. <code>EthTSyn.c</code> aggregiert die Modul-Header sowie die externen BSW-Schnittstellen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für die Dateiorganisation und Inklusionshierarchie bei der BSW-Modulentwicklung von <code>EthTSyn</code>. Der optionale Einschluss von <code>Det.h</code> spiegelt den üblichen Präprozessorschalter für Entwicklungs-Fehlererkennung (<code>ETHTSYN_DEV_ERROR_DETECT</code>) wider. Auffällig ist die Benennung von <code>FrTSyn_Cfg.h</code>, die bei der Implementierung von <code>EthTSyn</code> redaktionell als <code>EthTSyn_Cfg.h</code> zu interpretieren bzw. abzugleichen ist. <code>EthTSyn_MemMap.h</code> ist für Speicherkonfiguration und Compilerabstraktion strikt einzubinden.</p>"}], "trans": [{"from": "FIG-97281b8bf6fa8057", "to": "FIG-f5c2fc5c1356e87a", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
